"""v3 control/animation tests in the exact shipped WebGL build. No alternate game model."""
from pathlib import Path
from playwright.sync_api import sync_playwright
import json, math, os
ROOT=Path(__file__).resolve().parents[1]
results=[];errors=[]
def check(name,ok,detail=None):
 results.append({'name':name,'pass':bool(ok),'detail':detail});print(('PASS ' if ok else 'FAIL ')+name, str(detail)[:350],flush=True)
with sync_playwright() as pw:
 browser=pw.chromium.launch(executable_path=os.environ.get('CHROMIUM_PATH','/usr/bin/chromium'),headless=True,args=['--no-sandbox','--use-gl=angle','--use-angle=gl-egl','--enable-webgl','--ignore-gpu-blocklist','--disable-dev-shm-usage'])
 page=browser.new_page(viewport={'width':1280,'height':720});page.on('pageerror',lambda e:errors.append(str(e)))
 page.set_content((ROOT/'index.html').read_text(),wait_until='load');ev=page.evaluate
 ev('HARBOR.manualTesting=true;HARBOR.hadLock=false')
 def reset():
  ev("""()=>{const g=HARBOR;g.reset('free',false);g.started=true;g.running=true;g.mode='play';g.closeOverlays();document.getElementById('startScreen').hidden=true;document.getElementById('hud').hidden=false;g.npcs=[];g.cars=g.cars.filter(c=>c.id==='target');g.cheats.god=true;g.cheats.noPolice=true;g.render.quality='low';g.shoulderSide=1;HARBOR_TEST.position([-128,0,167],Math.PI/2);g.player.grounded=true;HarborMotion.reset(g.player);g.updateCamera(1,true);g.toastTime=0;}""")
 reset();page.keyboard.press('z');page.keyboard.down('w');r=ev('HARBOR_TEST.step(90);({speed:HARBOR.player.moveSpeed,walk:HARBOR.walkMode,state:HARBOR.player.anim.state})');page.keyboard.up('w')
 check('Z selects a genuine walking gait at 1.65m/s',r['walk'] and 1.63<r['speed']<1.67 and r['state']=='walk',r)
 page.keyboard.down('Shift');page.keyboard.down('w');r=ev('HARBOR_TEST.step(45);({speed:HARBOR.player.moveSpeed,state:HARBOR.player.anim.state})');page.keyboard.up('Shift');page.keyboard.up('w')
 check('Sprint overrides walk mode without changing forward heading',r['speed']>6.4 and r['state']=='sprint',r)
 reset();ev("HARBOR.keys.add('ControlLeft');HARBOR.keys.add('ShiftLeft');HARBOR.keys.add('KeyW');HARBOR_TEST.step(45)")
 check('Sneak has priority over simultaneous sprint input',ev('HARBOR.player.moveSpeed')<1.71)
 reset();r=ev("""()=>{const g=HARBOR;g.keys.add('KeyS');let max=0,prev=g.player.yaw;for(let i=0;i<60;i++){g.step(1/60);max=Math.max(max,Math.abs(HM.angle(prev,g.player.yaw)));prev=g.player.yaw;}return{max,alignment:Math.cos(HM.angle(g.player.yaw,-Math.PI/2))};}""")
 check('180 degree direction reversal has a bounded angular step',r['max']<=.150001 and r['alignment']>.999,r)
 reset();r=ev("""()=>{const g=HARBOR,p=g.player;g.input.aim=true;let lift=0,pivots=0,start=p.pos.slice();for(let i=0;i<100;i++){g.cam.yaw+=.026;g.step(1/60);if(p.anim.state==='pivot')pivots++;lift=Math.max(lift,...p.anim.localFeet.map(f=>f[1]));}return{pivots,lift,drift:HM.len(HM.sub(start,p.pos)),footfall:p.anim.footfall};}""")
 check('Stationary aim rotation replaces feet rather than skating',r['pivots']>40 and r['lift']>.17 and r['drift']<1e-6,r)
 check('Pivot can create contact events without translating the actor',r['footfall']>=1,r)
 reset();r=ev("""()=>{const g=HARBOR,p=g.player;g.jump();let previous=null,maxAir=0;for(let i=0;i<55;i++){g.step(1/60);if(!p.grounded){const v=HarborMotion.pose(p).legs.flatMap(l=>l.ankle);if(previous)maxAir=Math.max(maxAir,...v.map((x,j)=>Math.abs(x-previous[j])));previous=v;}else previous=null;}return maxAir;}""")
 check('Airborne pose remains continuous through ascent, apex and descent',r<.055,{'maxAnkleCoordinateChangePerTick':r})
 reset();r=ev("""()=>{const g=HARBOR,p=g.player;g.jump();let launches=0,last=true;for(let i=0;i<100;i++){if(!p.grounded&&p.vel[1]<-3&&p.pos[1]<.16&&!g.buffered){g.jump();g.buffered=true;}g.step(1/60);if(last&&!p.grounded)launches++;last=p.grounded;}delete g.buffered;return launches;}""")
 check('Jump just before landing is buffered into one follow-up jump',r==2,r)
 reset();r=ev("""()=>{const g=HARBOR,p=g.player;p.grounded=false;p.pos[1]=.04;p.coyote=.06;p.vel[1]=-.2;g.jump();for(let i=0;i<15;i++)g.step(1/60);return{y:p.pos[1],vy:p.vel[1]};}""")
 check('Coyote-time input still launches after a small ledge',r['y']>.55,r)
 reset();r=ev("""()=>{const g=HARBOR,p=g.player;g.world.boxes.push({id:'fixture-curb',min:[-125,0,165],max:[-122,.24,169]});g.keys.add('KeyW');let top=0;for(let i=0;i<90;i++){g.step(1/60);top=Math.max(top,p.pos[1]);}g.world.boxes=g.world.boxes.filter(b=>b.id!=='fixture-curb');return {x:p.pos[0],top,grounded:p.grounded};}""")
 check('A 24cm curb is crossed by walking without a jump input',r['x']>-122.5 and .239<=r['top']<.27,r)
 reset();r=ev("""()=>{const g=HARBOR,p=g.player;g.world.boxes.push({id:'fixture-barrier',min:[-125,0,165],max:[-124,.52,169]});g.keys.add('KeyW');for(let i=0;i<100;i++)g.step(1/60);let blocked=p.pos[0];g.jump();for(let i=0;i<105;i++)g.step(1/60);g.world.boxes=g.world.boxes.filter(b=>b.id!=='fixture-barrier');return {blocked,x:p.pos[0],ground:p.grounded};}""")
 check('A 52cm barrier blocks walking but can be jumped',r['blocked']<-125.3 and r['x']>-123.0 and r['ground'],r)
 reset();r=ev("""()=>{const g=HARBOR;const old=g.cam.pos.slice(),player=g.player.pos.slice(),yaw=g.cam.yaw;g.swapShoulder();for(let i=0;i<30;i++)g.step(1/60);const right=[Math.cos(yaw),0,Math.sin(yaw)];return {shift:HM.dot(HM.sub(g.cam.pos,old),right),drift:HM.len(HM.sub(g.player.pos,player)),yaw:g.cam.yaw-yaw};}""")
 check('Shoulder swap moves camera across the character without moving aim or body',r['shift']< -1.2 and r['drift']==0 and r['yaw']==0,r)
 reset();r=ev("""()=>{const g=HARBOR;g.world.boxes.push({id:'camera-wall',min:[-134,0,164],max:[-132,4,170]});g.updateCamera(1,true);let inside=0,cut=0;for(let i=0;i<90;i++){g.cam.yaw+=.013;g.step(1/60);const q=g.cam.pos;if(q[0]>-134&&q[0]<-132&&q[1]>0&&q[1]<4&&q[2]>164&&q[2]<170)inside++;if(g.cam.blocked)cut++;}g.world.boxes=g.world.boxes.filter(b=>b.id!=='camera-wall');return {inside,cut};}""")
 check('Camera orbit contracts before wall intersection',r['inside']==0 and r['cut']>0,r)
 reset();r=ev("""()=>{const g=HARBOR;g.cameraShake=0;g.shake=.4;const seen=[],real=g.render.render;g.render.render=(cam)=>seen.push(JSON.stringify(cam));g.renderWorld();g.renderWorld();g.render.render=real;return seen[0]===seen[1];}""")
 check('Zero camera-shake setting removes stochastic camera displacement',r)
 reset();r=ev("""()=>{const g=HARBOR,p=g.player;g.keys.add('KeyW');for(let i=0;i<25;i++)g.step(1/60);const before=JSON.stringify(p),old=g.prevVisual,out=HarborMotion.visual(p,old,.5);return {mid:out.pos[0],expected:(p.pos[0]+old.pos[0])/2,pure:before===JSON.stringify(p),finite:HarborMotion.pose(out).legs.flatMap(l=>l.ankle).every(Number.isFinite)};}""")
 check('Render interpolation is halfway between fixed-tick poses',abs(r['mid']-r['expected'])<1e-8 and r['finite'],r)
 check('Interpolated render sampling does not mutate gameplay state',r['pure'])
 reset();r=ev("""()=>{const g=HARBOR;g.baseFov=80;g.input.aim=true;for(let i=0;i<90;i++)g.step(1/60);const aim=g.cam.fov;g.input.aim=false;for(let i=0;i<90;i++)g.step(1/60);return{aim,normal:g.cam.fov};}""")
 check('Field-of-view preference preserves ADS FOV and restores on release',abs(r['aim']-50)<.01 and abs(r['normal']-80)<.01,r)
 reset();ev('HARBOR.toTitle()');page.locator('#startMotion').click();ev('HARBOR.hadLock=false;HARBOR.manualTesting=true;HARBOR.render.quality="medium"');r=ev('({lab:HARBOR.lab,phase:HARBOR.phase,npcs:HARBOR.npcs.length,boxes:HARBOR.world.boxes.filter(b=>b.lab).length,ui:!document.getElementById("labInfo").hidden})')
 check('Motion test course starts from the visible menu button',r['lab'] and r['phase']=='free' and r['npcs']==0 and r['boxes']==2 and r['ui'],r)
 r=ev("""()=>{const g=HARBOR,n=g.world.boxes.length;let rejected=false;try{g.restore({version:999});}catch(e){rejected=true;}return {rejected,lab:g.lab,unchanged:g.world.boxes.length===n};}""")
 check('Invalid save import cannot mutate the active training session',r['rejected'] and r['lab'] and r['unchanged'],r)
 r=ev("""()=>{const g=HARBOR,old=g.player.hp;g.hurt(80);g.crime(3,'lab');g.shoot();HARBOR_TEST.step(10);return {hp:g.player.hp,old,level:g.wanted.level,events:g.events.length,save:g.save()};}""")
 check('Motion lab is safe and cannot overwrite the campaign save',r['hp']==r['old'] and r['level']==0 and r['events']==0 and r['save'] is False,r)
 ev('HARBOR.resetLabPosition();HARBOR_TEST.step(1);HARBOR.updateHUD();HARBOR_TEST.render()');page.screenshot(path=str(ROOT/'reports/motion-lab-v3.png'))
 ev('HARBOR.keys.add("KeyW");HARBOR_TEST.step(25)');page.keyboard.press('t');check('T resets training position and clears movement input',ev('Math.abs(HARBOR.player.pos[0]+128)<.001 && HARBOR.keys.size===0'))
 ev('HARBOR.reset("mission",false)');r=ev('({lab:HARBOR.lab,phase:HARBOR.phase,boxes:HARBOR.world.boxes.filter(b=>b.lab).length,npcs:HARBOR.npcs.length})')
 check('Mission restart removes all training-only collision objects',not r['lab'] and r['boxes']==0 and r['phase']=='reach' and r['npcs']>0,r)
 reset();ev("HARBOR.hadLock=false;HARBOR.pause()");page.locator('#cameraShake').fill('0');page.locator('#cameraFov').fill('75');check('New camera settings update through the real UI',ev('HARBOR.cameraShake===0 && HARBOR.baseFov===75'))
 check('WebGL error state remains clean',ev('HARBOR.render.gl.getError()')==0)
 check('No uncaught runtime errors',not errors,errors)
 # Touch branch runs the SAME shoulder action.
 mobile=browser.new_context(viewport={'width':891,'height':411},is_mobile=True,has_touch=True,device_scale_factor=1)
 mp=mobile.new_page();mp.on('pageerror',lambda e:errors.append(str(e)));mp.set_content((ROOT/'index.html').read_text(),wait_until='load');mp.locator('#startMotion').tap();mp.evaluate('HARBOR.manualTesting=true');side=mp.evaluate('HARBOR.shoulderSide');mp.locator('#shoulderBtn').tap()
 check('Touch shoulder button changes camera side',mp.evaluate('HARBOR.shoulderSide')==-side)
 r=mp.locator('#startMotion').count();mp.evaluate('HARBOR.renderWorld();HARBOR.updateHUD()');mp.screenshot(path=str(ROOT/'reports/mobile-v3.png'))
 check('Motion HUD fits in the emulated 891x411 viewport',mp.evaluate('document.body.scrollWidth<=innerWidth && document.getElementById("labInfo").getBoundingClientRect().right<=innerWidth+1'))
 report={'suite':'v3 polish in shipped WebGL game','passed':sum(x['pass'] for x in results),'total':len(results),'results':results,'errors':errors,'physicalDeviceTested':False}
 (ROOT/'reports/polish-browser-results.json').write_text(json.dumps(report,ensure_ascii=False,indent=2));browser.close();print('TOTAL',report['passed'],'/',report['total'])
 if report['passed']!=report['total']:raise SystemExit(1)
